using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

[Collection("NotificationService")]
public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain the static queue to prevent cross-test pollution
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain again on teardown for safety
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    // ---------------------------------------------------------------
    // 1. SendNotification with display name
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_WithDisplayName_MessageContainsTypeAndDisplayNameAndOperation()
    {
        _sut.SendNotification("Student", "42", "Alice Smith", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("Student", notification.Message);
        Assert.Contains("Alice Smith", notification.Message);
        Assert.StartsWith("New", notification.Message);
        Assert.Contains("has been created", notification.Message);
        // Verify the exact expected format
        Assert.Equal("New Student 'Alice Smith' has been created", notification.Message);
    }

    // ---------------------------------------------------------------
    // 2. SendNotification without display name — uses ID format
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_WithoutDisplayName_MessageUsesIdFormat()
    {
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE, "teacher");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("(ID: 101)", notification.Message);
        Assert.DoesNotContain("'", notification.Message); // no quoted display name
        Assert.Equal("Course (ID: 101) has been updated", notification.Message);
    }

    // ---------------------------------------------------------------
    // 3. SendNotification with userName — CreatedBy is set
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_WithUserName_SetsCreatedByToThatUser()
    {
        _sut.SendNotification("Department", "5", "Engineering", EntityOperation.CREATE, "jdoe");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("jdoe", notification.CreatedBy);
        Assert.NotEqual("System", notification.CreatedBy);
    }

    // ---------------------------------------------------------------
    // 4. SendNotification without userName — defaults to "System"
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_WithoutUserName_CreatedByDefaultsToSystem()
    {
        _sut.SendNotification("Student", "7", "Bob", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithNullUserName_CreatedByDefaultsToSystem()
    {
        _sut.SendNotification("Student", "7", "Bob", EntityOperation.DELETE, null);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    // ---------------------------------------------------------------
    // 5. ReceiveNotification dequeues FIFO
    // ---------------------------------------------------------------
    [Fact]
    public void ReceiveNotification_DequeuedInFifoOrder()
    {
        _sut.SendNotification("Course", "1", "Math", EntityOperation.CREATE);
        _sut.SendNotification("Course", "2", "Science", EntityOperation.UPDATE);
        _sut.SendNotification("Course", "3", "English", EntityOperation.DELETE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        var third = _sut.ReceiveNotification();

        Assert.NotNull(first);
        Assert.NotNull(second);
        Assert.NotNull(third);
        Assert.Equal("1", first.EntityId);
        Assert.Equal("2", second.EntityId);
        Assert.Equal("3", third.EntityId);
        Assert.Contains("Math", first.Message);
        Assert.Contains("Science", second.Message);
        Assert.Contains("English", third.Message);
    }

    // ---------------------------------------------------------------
    // 6. ReceiveNotification returns null when queue is empty
    // ---------------------------------------------------------------
    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _sut.ReceiveNotification();

        Assert.Null(result);
    }

    // ---------------------------------------------------------------
    // 7. Operation property is set to operation.ToString()
    // ---------------------------------------------------------------
    [Theory]
    [InlineData(EntityOperation.CREATE, "CREATE")]
    [InlineData(EntityOperation.UPDATE, "UPDATE")]
    [InlineData(EntityOperation.DELETE, "DELETE")]
    public void SendNotification_SetsOperationPropertyToEnumString(EntityOperation op, string expectedString)
    {
        _sut.SendNotification("Instructor", "10", "Dr. Smith", op, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal(expectedString, notification.Operation);
    }

    // ---------------------------------------------------------------
    // 8. IsRead is set to false
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _sut.SendNotification("Student", "99", "Eve", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }

    // ---------------------------------------------------------------
    // 9. CREATE message starts with "New"
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_CreateOperation_MessageStartsWithNew()
    {
        _sut.SendNotification("Enrollment", "300", "Fall 2024", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.StartsWith("New", notification.Message);
        Assert.Contains("has been created", notification.Message);
        // UPDATE/DELETE must NOT start with "New" — verify the distinction matters
    }

    [Fact]
    public void SendNotification_UpdateOperation_MessageDoesNotStartWithNew()
    {
        _sut.SendNotification("Enrollment", "300", "Fall 2024", EntityOperation.UPDATE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.DoesNotContain("New ", notification.Message);
    }

    // ---------------------------------------------------------------
    // 10. UPDATE message contains "has been updated"
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_UpdateOperation_MessageContainsHasBeenUpdated()
    {
        _sut.SendNotification("Department", "4", "Biology", EntityOperation.UPDATE, "chair");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("has been updated", notification.Message);
        Assert.Equal("Department 'Biology' has been updated", notification.Message);
        Assert.DoesNotContain("created", notification.Message);
        Assert.DoesNotContain("deleted", notification.Message);
    }

    // ---------------------------------------------------------------
    // 11. DELETE message contains "has been deleted"
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_DeleteOperation_MessageContainsHasBeenDeleted()
    {
        _sut.SendNotification("Course", "55", "Organic Chemistry", EntityOperation.DELETE, "dean");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("has been deleted", notification.Message);
        Assert.Equal("Course 'Organic Chemistry' has been deleted", notification.Message);
        Assert.DoesNotContain("created", notification.Message);
        Assert.DoesNotContain("updated", notification.Message);
    }

    // ---------------------------------------------------------------
    // 12. Queue cap enforcement — max 500
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_ExceedingMaxQueueLength_CapsAtMaximum()
    {
        // Send 502 items to exceed the 500 cap
        for (int i = 0; i < 502; i++)
        {
            _sut.SendNotification("Item", i.ToString(), $"Item{i}", EntityOperation.CREATE, "bulk");
        }

        // Drain the queue and count how many remain
        int count = 0;
        while (_sut.ReceiveNotification() != null)
        {
            count++;
        }

        Assert.True(count <= 500, $"Queue should be capped at 500 but had {count} items");
        Assert.True(count > 0, "Queue should not be empty after adding items");
    }

    // ---------------------------------------------------------------
    // 13. Dispose does not throw
    // ---------------------------------------------------------------
    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var exception = Record.Exception(() => service.Dispose());
        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_CanBeCalledMultipleTimes_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex1 = Record.Exception(() => service.Dispose());
        var ex2 = Record.Exception(() => service.Dispose());
        Assert.Null(ex1);
        Assert.Null(ex2);
    }

    // ---------------------------------------------------------------
    // 14. MarkAsRead does not throw (no-op)
    // ---------------------------------------------------------------
    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var exception = Record.Exception(() => _sut.MarkAsRead(42));
        Assert.Null(exception);
    }

    [Fact]
    public void MarkAsRead_WithZeroId_DoesNotThrow()
    {
        var exception = Record.Exception(() => _sut.MarkAsRead(0));
        Assert.Null(exception);
    }

    [Fact]
    public void MarkAsRead_WithNegativeId_DoesNotThrow()
    {
        var exception = Record.Exception(() => _sut.MarkAsRead(-1));
        Assert.Null(exception);
    }

    // ---------------------------------------------------------------
    // 15. 4-param overload delegates to 5-param — identical behavior
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_FourParamOverload_ProducesSameResultAsFiveParamWithNullDisplayName()
    {
        // Use the 4-param overload (entityType, entityId, operation, userName)
        _sut.SendNotification("Student", "77", EntityOperation.CREATE, "admin");
        var fromFourParam = _sut.ReceiveNotification();

        // Use the 5-param overload with null display name
        _sut.SendNotification("Student", "77", null, EntityOperation.CREATE, "admin");
        var fromFiveParam = _sut.ReceiveNotification();

        Assert.NotNull(fromFourParam);
        Assert.NotNull(fromFiveParam);
        // Both should produce the ID-based format since no display name
        Assert.Equal(fromFourParam.Message, fromFiveParam.Message);
        Assert.Equal(fromFourParam.EntityType, fromFiveParam.EntityType);
        Assert.Equal(fromFourParam.EntityId, fromFiveParam.EntityId);
        Assert.Equal(fromFourParam.Operation, fromFiveParam.Operation);
        Assert.Equal(fromFourParam.CreatedBy, fromFiveParam.CreatedBy);
        Assert.Equal(fromFourParam.IsRead, fromFiveParam.IsRead);
        // Verify the message uses ID format, not display name format
        Assert.Contains("(ID: 77)", fromFourParam.Message);
    }

    // ---------------------------------------------------------------
    // Additional: EntityType and EntityId are set correctly
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_SetsEntityTypeAndEntityIdCorrectly()
    {
        _sut.SendNotification("Instructor", "42", "Dr. Jones", EntityOperation.UPDATE, "user1");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Instructor", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
    }

    // ---------------------------------------------------------------
    // Additional: CreatedAt is set to approximately now
    // ---------------------------------------------------------------
    [Fact]
    public void SendNotification_SetsCreatedAtToApproximatelyNow()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _sut.SendNotification("Course", "10", "Algebra", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    // ---------------------------------------------------------------
    // Additional: Empty display name treated as no display name
    // ---------------------------------------------------------------
    [Theory]
    [InlineData("")]
    [InlineData("   ")]
    public void SendNotification_WithWhitespaceDisplayName_FallsBackToIdFormat(string displayName)
    {
        _sut.SendNotification("Student", "88", displayName, EntityOperation.DELETE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("(ID: 88)", notification.Message);
        Assert.DoesNotContain("'", notification.Message);
    }
}

