namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        private static SchoolContext GetDbContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfStudents()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfInstructors()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfDepartments()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfCourses()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfOfficeAssignments()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfCourseAssignments()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_SeedsCorrectNumberOfEnrollments()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_IsIdempotent_CallingTwiceDoesNotDuplicateData()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());

            DbInitializer.Initialize(context);
            DbInitializer.Initialize(context);

            // All counts should remain the same after second call
            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Equal(8, context.CourseAssignments.Count());
            Assert.Equal(11, context.Enrollments.Count());
        }

