        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

            var alexander = context.Students.SingleOrDefault(s => s.LastName == "Alexander");
            Assert.NotNull(alexander);
            Assert.Equal("Carson", alexander.FirstMidName);
            Assert.Equal(DateTime.Parse("2010-09-01"), alexander.EnrollmentDate);
        }

        [Fact]
        public void Initialize_SeedsStudentOlivetto()
        {
            using var context = GetDbContext(Guid.NewGuid().ToString());
            DbInitializer.Initialize(context);

