using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        private static SchoolContext GetDbContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public HomeControllerTests()
        {
            _context = GetDbContext(Guid.NewGuid().ToString());
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Null(viewResult.ViewName); // default view
        }

        [Fact]
        public void About_WithNoStudents_ReturnsEmptyList()
        {
            // Act
            var result = _controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Empty(model);
        }

        [Fact]
        public void About_WithStudents_ReturnsCorrectEnrollmentDateGroups()
        {
            // Arrange — 3 students: 2 on same date, 1 on different date
            var sharedDate = DateTime.Parse("2023-09-01");
            var uniqueDate = DateTime.Parse("2024-01-15");

            _context.Students.AddRange(
                new Student { FirstMidName = "Alice", LastName = "One", EnrollmentDate = sharedDate },
                new Student { FirstMidName = "Bob", LastName = "Two", EnrollmentDate = sharedDate },
                new Student { FirstMidName = "Carol", LastName = "Three", EnrollmentDate = uniqueDate }
            );
            _context.SaveChanges();

            // Act
            var result = _controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Equal(2, model.Count);

            var sharedGroup = model.Single(g => g.EnrollmentDate == sharedDate);
            Assert.Equal(2, sharedGroup.StudentCount);

            var uniqueGroup = model.Single(g => g.EnrollmentDate == uniqueDate);
            Assert.Equal(1, uniqueGroup.StudentCount);
        }

        [Fact]
        public void About_WithStudents_SumsCountsToTotalStudents()
        {
            // Arrange — verify that total across groups matches actual student count
            _context.Students.AddRange(
                new Student { FirstMidName = "A", LastName = "X", EnrollmentDate = DateTime.Parse("2020-01-01") },
                new Student { FirstMidName = "B", LastName = "Y", EnrollmentDate = DateTime.Parse("2020-01-01") },
                new Student { FirstMidName = "C", LastName = "Z", EnrollmentDate = DateTime.Parse("2021-06-01") }
            );
            _context.SaveChanges();

            // Act
            var result = _controller.About();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
            Assert.Equal(3, model.Sum(g => g.StudentCount));
        }

        [Fact]
        public void Contact_ReturnsViewResult_AndSetsViewBagMessage()
        {
            // Act
            var result = _controller.Contact();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal("Your contact page.", _controller.ViewBag.Message);
            // Also verify the exact string to catch typos
            Assert.Contains("contact", (string)_controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsViewResult()
        {
            // Act
            var result = _controller.Error();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Null(viewResult.ViewName);
        }

        [Fact]
        public void Unauthorized_ReturnsViewResult_AndSetsPermissionMessage()
        {
            // Act
            var result = _controller.Unauthorized();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            string message = _controller.ViewBag.Message;
            Assert.Equal("You don't have permission to access this resource.", message);
            // Verify key phrases to catch partial rewording
            Assert.Contains("permission", message);
            Assert.Contains("resource", message);
        }
    }
}

