using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private SchoolContext _context;
        private StudentsController _controller;

        private SchoolContext CreateContext(string dbName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private StudentsController CreateController(SchoolContext context)
        {
            var controller = new StudentsController(context);
            // Set up TempData so DeleteConfirmed doesn't throw
            var httpContext = new DefaultHttpContext();
            var tempData = new TempDataDictionary(httpContext, Mock.Of<ITempDataProvider>());
            controller.TempData = tempData;
            return controller;
        }

        private void SeedThreeStudents(SchoolContext context)
        {
            context.Students.AddRange(
                new Student { LastName = "Carson", FirstMidName = "Alexander", EnrollmentDate = new DateTime(2020, 9, 1) },
                new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2019, 9, 1) },
                new Student { LastName = "Baker", FirstMidName = "Fadi", EnrollmentDate = new DateTime(2021, 1, 15) }
            );
            context.SaveChanges();
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        // ─── Index Tests ────────────────────────────────────────────────

        [Fact]
        public void Index_NoParams_ReturnsStudentsOrderedByLastName()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(3, model.Count);
            // Default sort: LastName ascending → Alonso, Baker, Carson
            Assert.Equal("Alonso", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Carson", model[2].LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsStudentsDescending()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            var result = _controller.Index("name_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(3, model.Count);
            // name_desc sort: LastName descending → Carson, Baker, Alonso
            Assert.Equal("Carson", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Alonso", model[2].LastName);
        }

        [Fact]
        public void Index_DateSort_ReturnsSortedByDateAscending()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            var result = _controller.Index("Date", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            // Date ascending: Alonso(2019), Carson(2020), Baker(2021)
            Assert.Equal("Alonso", model[0].LastName);
            Assert.Equal("Carson", model[1].LastName);
            Assert.Equal("Baker", model[2].LastName);
        }

        [Fact]
        public void Index_DateDescSort_ReturnsSortedByDateDescending()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            var result = _controller.Index("date_desc", null, null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            // Date descending: Baker(2021), Carson(2020), Alonso(2019)
            Assert.Equal("Baker", model[0].LastName);
            Assert.Equal("Carson", model[1].LastName);
            Assert.Equal("Alonso", model[2].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByLastName()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, "Carson", null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Carson", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudentsByFirstName()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, "Meredith", null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Meredith", model[0].FirstMidName);
            Assert.Equal("Alonso", model[0].LastName);
        }

        [Fact]
        public void Index_SearchStringNull_UsesCurrentFilter()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            // When searchString is null, currentFilter should be used as the search term
            var result = _controller.Index(null, "Baker", null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
            // ViewBag.CurrentFilter should reflect the filter in use
            Assert.Equal("Baker", viewResult.ViewData["CurrentFilter"]);
        }

        [Fact]
        public void Index_SearchStringProvided_ResetsPageTo1()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            // When searchString is provided (non-null), page resets to 1
            // Even passing page=2, the result should be page 1 because searchString resets it
            var result = _controller.Index(null, null, "A", 2);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            // "A" matches Alonso (FirstMidName="Meredith" doesn't contain "A"... but LastName="Alonso" does)
            // Also Carson has "Alexander" in FirstMidName, and Baker has LastName "Baker" with "a" — InMemory is case-sensitive by default
            // Let's just verify PageIndex is 1
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_Pagination_ReturnsCorrectPage()
        {
            _context = CreateContext();
            // Add 15 students (page size is 10, so page 2 should have 5)
            for (int i = 1; i <= 15; i++)
            {
                _context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = $"First{i:D2}",
                    EnrollmentDate = new DateTime(2020, 1, i)
                });
            }
            _context.SaveChanges();
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, null, 2);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(5, model.Count);
            Assert.Equal(2, model.PageIndex);
            Assert.Equal(2, model.TotalPages);
            Assert.True(model.HasPreviousPage);
            Assert.False(model.HasNextPage);
        }

        // ─── Details Tests ──────────────────────────────────────────────

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            _context = CreateContext();
            _controller = CreateController(_context);

            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsStudentView()
        {
            _context = CreateContext();
            // Add student with an enrollment
            var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 0 };
            _context.Courses.Add(course);
            var student = new Student
            {
                LastName = "Kapoor",
                FirstMidName = "Nino",
                EnrollmentDate = new DateTime(2021, 9, 1),
                Enrollments = new List<Enrollment>
                {
                    new Enrollment { CourseID = 1050, Grade = Grade.A }
                }
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            _controller = CreateController(_context);

            var result = _controller.Details(student.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal("Kapoor", model.LastName);
            Assert.Equal("Nino", model.FirstMidName);
            Assert.NotNull(model.Enrollments);
            Assert.Single(model.Enrollments);
            Assert.Equal(Grade.A, model.Enrollments.First().Grade);
        }

        [Fact]
        public void Details_InvalidId_ThrowsInvalidOperationException()
        {
            _context = CreateContext();
            _controller = CreateController(_context);

            // .Single() on empty sequence throws InvalidOperationException
            Assert.Throws<InvalidOperationException>(() => _controller.Details(999));
        }

        // ─── Create GET Tests ───────────────────────────────────────────

        [Fact]
        public void Create_GET_ReturnsViewWithStudentHavingTodayDate()
        {
            _context = CreateContext();
            _controller = CreateController(_context);

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // ─── Create POST Tests ──────────────────────────────────────────

        [Fact]
        public void Create_POST_ValidStudent_SavesAndRedirects()
        {
            _context = CreateContext();
            _controller = CreateController(_context);
            var student = new Student
            {
                LastName = "TestLast",
                FirstMidName = "TestFirst",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            // Verify student was persisted
            Assert.Equal(1, _context.Students.Count());
            var saved = _context.Students.Single();
            Assert.Equal("TestLast", saved.LastName);
            Assert.Equal("TestFirst", saved.FirstMidName);
            Assert.Equal(new DateTime(2023, 9, 1), saved.EnrollmentDate);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsView()
        {
            _context = CreateContext();
            _controller = CreateController(_context);
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "NoLast",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Student>(viewResult.Model);
            Assert.Equal("NoLast", model.FirstMidName);
            // Student should not have been saved
            Assert.Equal(0, _context.Students.Count());
        }

        [Fact]
        public void Create_POST_MinValueDate_AddsModelError()
        {
            _context = CreateContext();
            _controller = CreateController(_context);
            var student = new Student
            {
