        [Fact]
        public void Index_SearchStringNull_UsesCurrentFilter()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            // When searchString is null, currentFilter should be used as the search term
            var result = _controller.Index(null, "Baker", null, null);

            var viewResult = Assert.IsType<ViewResult>(result);
