        }

        [Fact]
        public void Index_SearchStringProvided_ResetsPageTo1()
        {
            _context = CreateContext();
            SeedThreeStudents(_context);
            _controller = CreateController(_context);

            // When searchString is provided (non-null), page resets to 1
            // Even passing page=2, the result should be page 1 because searchString resets it
            var result = _controller.Index(null, null, "A", 2);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            // "A" matches Alonso (FirstMidName="Meredith" doesn't contain "A"... but LastName="Alonso" does)
            // Also Carson has "Alexander" in FirstMidName, and Baker has LastName "Baker" with "a" — InMemory is case-sensitive by default
            // Let's just verify PageIndex is 1
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_Pagination_ReturnsCorrectPage()
        {
            _context = CreateContext();
            // Add 15 students (page size is 10, so page 2 should have 5)
            for (int i = 1; i <= 15; i++)
            {
                _context.Students.Add(new Student
                {
                    LastName = $"Student{i:D2}",
                    FirstMidName = $"First{i:D2}",
                    EnrollmentDate = new DateTime(2020, 1, i)
                });
            }
            _context.SaveChanges();
            _controller = CreateController(_context);

            var result = _controller.Index(null, null, null, 2);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
            Assert.Equal(5, model.Count);
            Assert.Equal(2, model.PageIndex);
            Assert.Equal(2, model.TotalPages);
            Assert.True(model.HasPreviousPage);
            Assert.False(model.HasNextPage);
        }

