using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly List<string> _tempDirs = new();

        private SchoolContext CreateContext(string dbName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private (Mock<IWebHostEnvironment> env, Mock<ILogger<CoursesController>> logger, string tempDir) CreateMocks()
        {
            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(tempDir);
            _tempDirs.Add(tempDir);
            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.ContentRootPath).Returns(tempDir);
            envMock.Setup(e => e.WebRootPath).Returns(tempDir);
            var loggerMock = new Mock<ILogger<CoursesController>>();
            return (envMock, loggerMock, tempDir);
        }

        private CoursesController CreateController(SchoolContext context, Mock<IWebHostEnvironment> envMock, Mock<ILogger<CoursesController>> loggerMock)
        {
            var controller = new CoursesController(context, envMock.Object, loggerMock.Object);
            var httpContext = new DefaultHttpContext();
            var tempData = new TempDataDictionary(httpContext, Mock.Of<ITempDataProvider>());
            controller.TempData = tempData;
            return controller;
        }

        private Department SeedDepartment(SchoolContext context, int id = 1, string name = "Engineering")
        {
            var dept = new Department
            {
                DepartmentID = id,
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(SchoolContext context, int courseId = 1050, string title = "Chemistry", int departmentId = 1)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = departmentId
            };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        private Mock<IFormFile> CreateMockFile(string fileName = "test.jpg", long length = 1024)
        {
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns(fileName);
            fileMock.Setup(f => f.Length).Returns(length);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => { });
            return fileMock;
        }

        public void Dispose()
        {
            foreach (var dir in _tempDirs)
            {
                try { Directory.Delete(dir, true); } catch { }
            }
        }

        // ─── Index Tests ────────────────────────────────────────────────

        [Fact]
        public void Index_ReturnsCoursesWithDepartment()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            var dept = SeedDepartment(context, 1, "Biology");
            SeedCourse(context, 2010, "Genetics", 1);
            SeedCourse(context, 2020, "Ecology", 1);

            using var controller = CreateController(context, envMock, loggerMock);
            var result = controller.Index() as ViewResult;

            Assert.NotNull(result);
            var courses = Assert.IsType<List<Course>>(result.Model);
            Assert.Equal(2, courses.Count);
            Assert.Contains(courses, c => c.CourseID == 2010 && c.Title == "Genetics");
            Assert.Contains(courses, c => c.CourseID == 2020 && c.Title == "Ecology");
            // Verify department is included (not null)
            Assert.All(courses, c => Assert.Equal("Biology", c.Department?.Name));
        }

        // ─── Details Tests ──────────────────────────────────────────────

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            using var controller = CreateController(context, envMock, loggerMock);

            var result = controller.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsCourseView()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            var dept = SeedDepartment(context);
            SeedCourse(context, 3010, "Physics", 1);

            using var controller = CreateController(context, envMock, loggerMock);
            var result = controller.Details(3010) as ViewResult;

            Assert.NotNull(result);
            var course = Assert.IsType<Course>(result.Model);
            Assert.Equal(3010, course.CourseID);
            Assert.Equal("Physics", course.Title);
            Assert.Equal(3, course.Credits);
        }

        [Fact]
        public void Details_InvalidId_ThrowsInvalidOperationException()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            SeedDepartment(context);

            using var controller = CreateController(context, envMock, loggerMock);

            Assert.Throws<InvalidOperationException>(() => controller.Details(9999));
        }

        // ─── Create GET Tests ───────────────────────────────────────────

        [Fact]
        public void Create_GET_ReturnsViewWithEmptyCourse()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            SeedDepartment(context, 1, "Math");
            SeedDepartment(context, 2, "Science");

            using var controller = CreateController(context, envMock, loggerMock);
            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var course = Assert.IsType<Course>(result.Model);
            Assert.Equal(0, course.CourseID);
            Assert.Null(course.Title);
            // ViewBag.DepartmentID is a SelectList
            Assert.NotNull(result.ViewData["DepartmentID"]);
            var selectList = Assert.IsAssignableFrom<Microsoft.AspNetCore.Mvc.Rendering.SelectList>(result.ViewData["DepartmentID"]);
            Assert.Equal(2, selectList.Count());
        }

        // ─── Create POST Tests ──────────────────────────────────────────

        [Fact]
        public void Create_POST_ValidCourse_NoFile_SavesAndRedirects()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            SeedDepartment(context);

            using var controller = CreateController(context, envMock, loggerMock);
            var course = new Course { CourseID = 4010, Title = "Calculus", Credits = 4, DepartmentID = 1 };

            var result = controller.Create(course, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            // Verify persisted in DB
            var saved = context.Courses.Find(4010);
            Assert.NotNull(saved);
            Assert.Equal("Calculus", saved.Title);
            Assert.Equal(4, saved.Credits);
            Assert.Null(saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_POST_ValidCourse_WithValidImage_SavesFileAndRedirects()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, tempDir) = CreateMocks();
            SeedDepartment(context);

            using var controller = CreateController(context, envMock, loggerMock);
            var course = new Course { CourseID = 4020, Title = "Algebra", Credits = 3, DepartmentID = 1 };
            var fileMock = CreateMockFile("photo.png", 2048);

            var result = controller.Create(course, fileMock.Object) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = context.Courses.Find(4020);
            Assert.NotNull(saved);
            Assert.StartsWith("/Uploads/TeachingMaterials/course_4020_", saved.TeachingMaterialImagePath);
            Assert.EndsWith(".png", saved.TeachingMaterialImagePath);
            // Verify file was actually created on disk
            var uploadsDir = Path.Combine(tempDir, "Uploads", "TeachingMaterials");
            Assert.True(Directory.Exists(uploadsDir));
            Assert.Single(Directory.GetFiles(uploadsDir));
        }

        [Fact]
        public void Create_POST_InvalidExtension_AddsModelError()
        {
            using var context = CreateContext();
            var (envMock, loggerMock, _) = CreateMocks();
            SeedDepartment(context);

            using var controller = CreateController(context, envMock, loggerMock);
            var course = new Course { CourseID = 4030, Title = "History", Credits = 3, DepartmentID = 1 };
            var fileMock = CreateMockFile("malware.exe", 512);

            var result = controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.False(controller.ModelState.IsValid);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
            var error = controller.ModelState["teachingMaterialImage"]!.Errors.First();
            Assert.Contains("valid image file", error.ErrorMessage);
            // Course should NOT be saved
            Assert.Null(context.Courses.Find(4030));
        }

        [Fact]
