        private readonly List<string> _tempDirs = new();

        private SchoolContext CreateContext(string dbName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private (Mock<IWebHostEnvironment> env, Mock<ILogger<CoursesController>> logger, string tempDir) CreateMocks()
        {
            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(tempDir);
            _tempDirs.Add(tempDir);
            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.ContentRootPath).Returns(tempDir);
            envMock.Setup(e => e.WebRootPath).Returns(tempDir);
            var loggerMock = new Mock<ILogger<CoursesController>>();
            return (envMock, loggerMock, tempDir);
        }

        private CoursesController CreateController(SchoolContext context, Mock<IWebHostEnvironment> envMock, Mock<ILogger<CoursesController>> loggerMock)
        {
            var controller = new CoursesController(context, envMock.Object, loggerMock.Object);
            var httpContext = new DefaultHttpContext();
            var tempData = new TempDataDictionary(httpContext, Mock.Of<ITempDataProvider>());
            controller.TempData = tempData;
            return controller;
        }

        private Department SeedDepartment(SchoolContext context, int id = 1, string name = "Engineering")
        {
            var dept = new Department
            {
                DepartmentID = id,
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(dept);
            context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(SchoolContext context, int courseId = 1050, string title = "Chemistry", int departmentId = 1)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = departmentId
            };
            context.Courses.Add(course);
            context.SaveChanges();
            return course;
        }

        private Mock<IFormFile> CreateMockFile(string fileName = "test.jpg", long length = 1024)
        {
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.FileName).Returns(fileName);
            fileMock.Setup(f => f.Length).Returns(length);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => { });
            return fileMock;
        }

        public void Dispose()
        {
            foreach (var dir in _tempDirs)
            {
                try { Directory.Delete(dir, true); } catch { }
            }
        }

