+using Microsoft.AspNetCore.Mvc.ViewFeatures;
+using Microsoft.EntityFrameworkCore;
+using Moq;
+using Xunit;
+
+namespace ContosoUniversity.Tests.Controllers
+{
+    public class DepartmentsControllerTests : IDisposable
+    {
+        private readonly List<SchoolContext> _contexts = new();
+
+        private SchoolContext CreateContext(string dbName = null)
+        {
+            var options = new DbContextOptionsBuilder<SchoolContext>()
+                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
+                .Options;
+            var context = new SchoolContext(options);
+            _contexts.Add(context);
+            return context;
+        }
+
+        private DepartmentsController CreateController(SchoolContext context)
+        {
+            var controller = new DepartmentsController(context);
+            var httpContext = new DefaultHttpContext();
+            var tempData = new TempDataDictionary(httpContext, Mock.Of<ITempDataProvider>());
+            controller.TempData = tempData;
+            return controller;
+        }
+
+        private Instructor SeedInstructor(SchoolContext context, int id = 1, string lastName = "Smith", string firstName = "John")
+        {
+            var instructor = new Instructor
+            {
+                ID = id,
+                LastName = lastName,
+                FirstMidName = firstName,
+                HireDate = new DateTime(2010, 6, 15)
+            };
+            context.Instructors.Add(instructor);
+            context.SaveChanges();
+            return instructor;
+        }
+
+        private Department SeedDepartment(SchoolContext context, int id = 1, string name = "Engineering", decimal budget = 150000m, int? instructorId = null)
+        {
+            var dept = new Department
+            {
+                DepartmentID = id,
+                Name = name,
+                Budget = budget,
+                StartDate = new DateTime(2020, 9, 1),
+                InstructorID = instructorId
+            };
+            context.Departments.Add(dept);
+            context.SaveChanges();
+            return dept;
+        }
+
+        public void Dispose()
+        {
+            foreach (var ctx in _contexts)
+            {
+                ctx.Dispose();
+            }
+        }
+
+        // ==================== Index ====================
+
+        [Fact]
+        public void Index_ReturnsDepartmentsView()
+        {
+            // Arrange
+            var context = CreateContext();
+            var instructor = SeedInstructor(context, 10, "Adams", "Alice");
+            SeedDepartment(context, 1, "Mathematics", 200000m, instructor.ID);
+            SeedDepartment(context, 2, "Physics", 180000m, null);
+            var controller = CreateController(context);
+
+            // Act
+            var result = controller.Index();
+
+            // Assert
+            var viewResult = Assert.IsType<ViewResult>(result);
+            var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
+            Assert.Equal(2, model.Count);
+            Assert.Contains(model, d => d.Name == "Mathematics" && d.Budget == 200000m);
+            Assert.Contains(model, d => d.Name == "Physics" && d.Budget == 180000m);
+            // Verify the one with an administrator has it loaded
+            var mathDept = model.Single(d => d.Name == "Mathematics");
+            Assert.NotNull(mathDept.Administrator);
+            Assert.Equal("Adams, Alice", mathDept.Administrator.FullName);
+        }
+
+        // ==================== Details ====================
+
+        [Fact]
+        public void Details_NullId_ReturnsBadRequest()
+        {
+            // Arrange
+            var context = CreateContext();
+            var controller = CreateController(context);
+
+            // Act
+            var result = controller.Details(null);
+
+            // Assert
+            var statusResult = Assert.IsType<StatusCodeResult>(result);
+            Assert.Equal(400, statusResult.StatusCode);
+        }
+
+        [Fact]
+        public void Details_ValidId_ReturnsDepartment()
+        {
+            // Arrange
+            var context = CreateContext();
+            SeedDepartment(context, 5, "Biology", 95000m);
+            var controller = CreateController(context);
+
+            // Act
+            var result = controller.Details(5);
+
+            // Assert
+            var viewResult = Assert.IsType<ViewResult>(result);
+            var model = Assert.IsType<Department>(viewResult.Model);
+            Assert.Equal(5, model.DepartmentID);
+            Assert.Equal("Biology", model.Name);
+            Assert.Equal(95000m, model.Budget);
+        }
+
+        [Fact]
