+
+            // Act
+            var result = controller.Details(999);
+
+            // Assert
+            Assert.IsType<NotFoundResult>(result);
+        }
+
+        // ==================== Create GET ====================
+
+        [Fact]
+        public void Create_GET_ReturnsViewWithInstructorSelectList()
+        {
+            // Arrange
+            var context = CreateContext();
+            SeedInstructor(context, 1, "Garcia", "Maria");
+            SeedInstructor(context, 2, "Lee", "David");
+            var controller = CreateController(context);
+
+            // Act
+            var result = controller.Create();
+
+            // Assert
+            var viewResult = Assert.IsType<ViewResult>(result);
+            var selectList = Assert.IsType<SelectList>(controller.ViewBag.InstructorID);
+            var items = selectList.Items.Cast<Instructor>().ToList();
+            Assert.Equal(2, items.Count);
+            // Verify the SelectList uses "ID" as value and "FullName" as text
+            Assert.Contains(items, i => i.FullName == "Garcia, Maria");
+            Assert.Contains(items, i => i.FullName == "Lee, David");
+        }
+
+        // ==================== Create POST ====================
+
+        [Fact]
