1. using System;
2. using System.Collections.Generic;
3. using Microsoft.EntityFrameworkCore;
4. using System.Linq;
5. using System.Net;
6. using ContosoUniversity.Data;
7. using ContosoUniversity.Models;
8. using ContosoUniversity.Models.SchoolViewModels;
9. using Microsoft.AspNetCore.Mvc;
10. using Microsoft.AspNetCore.Mvc.ModelBinding;
11. using System.Threading.Tasks;
12. using System.Linq.Expressions;
13. using Microsoft.Extensions.Configuration;
14. 
15. namespace ContosoUniversity.Controllers
16. {
17.     public class InstructorsController : BaseController
18.     {
19.         public InstructorsController(SchoolContext context) : base(context)
20.         {
21.         }
22. 
23.         // GET: Instructors - All roles can view
24.         public ActionResult Index(int? id, int? courseID)
25.         {
26.             var viewModel = new InstructorIndexData();
27.             viewModel.Instructors = db.Instructors
28.                 .Include(i => i.OfficeAssignment)
29.                 .Include(i => i.CourseAssignments)
30.                     .ThenInclude(c => c.Course)
31.                         .ThenInclude(d => d.Department)
32.                 .OrderBy(i => i.LastName);
33. 
34.             if (id != null)
35.             {
36.                 ViewBag.InstructorID = id.Value;
37.                 viewModel.Courses = viewModel.Instructors.Where(
38.                     i => i.ID == id.Value).Single().CourseAssignments.Select(s => s.Course);
39.             }
40. 
41.             if (courseID != null)
42.             {
43.                 ViewBag.CourseID = courseID.Value;
44.                 viewModel.Enrollments = viewModel.Courses.Where(
45.                     x => x.CourseID == courseID).Single().Enrollments;
46.             }
47. 
48.             return View(viewModel);
49.         }
50. 
51.         // GET: Instructors/Details/5 - All roles can view details
52.         public ActionResult Details(int? id)
53.         {
54.             if (id == null)
55.             {
56.                 return new StatusCodeResult((int)HttpStatusCode.BadRequest);
57.             }
58.             Instructor instructor = db.Instructors.Find(id);
59.             if (instructor == null)
60.             {
61.                 return NotFound();
62.             }
63.             return View(instructor);
64.         }
65. 
66.         // GET: Instructors/Create
67.         public ActionResult Create()
68.         {
69.             var instructor = new Instructor();
70.             instructor.CourseAssignments = new List<CourseAssignment>();
71.             PopulateAssignedCourseData(instructor);
72.             return View(instructor);
73.         }
74. 
75.         // POST: Instructors/Create
76.         [HttpPost]
77.         [ValidateAntiForgeryToken]
78.         public ActionResult Create([Bind("LastName", "FirstMidName", "HireDate", "OfficeAssignment")] Instructor instructor, string[] selectedCourses)
79.         {
80.             if (selectedCourses != null)
81.             {
82.                 instructor.CourseAssignments = new List<CourseAssignment>();
83.                 foreach (var course in selectedCourses)
84.                 {
85.                     var courseToAdd = new CourseAssignment { InstructorID = instructor.ID, CourseID = int.Parse(course) };
86.                     instructor.CourseAssignments.Add(courseToAdd);
87.                 }
88.             }
89.             if (ModelState.IsValid)
90.             {
91.                 db.Instructors.Add(instructor);
92.                 db.SaveChanges();
93. 
94.                 // Send notification for instructor creation
95.                 SendEntityNotification("Instructor", instructor.ID.ToString(), EntityOperation.CREATE);
96. 
97.                 return RedirectToAction("Index");
98.             }
99.             PopulateAssignedCourseData(instructor);
100.             return View(instructor);
101.         }
102. 
103.         // GET: Instructors/Edit/5
104.         public ActionResult Edit(int? id)
105.         {
106.             if (id == null)
107.             {
108.                 return new StatusCodeResult((int)HttpStatusCode.BadRequest);
109.             }
110.             Instructor instructor = db.Instructors
111.                 .Include(i => i.OfficeAssignment)
112.                 .Include(i => i.CourseAssignments)
113.                     .ThenInclude(c => c.Course)
114.                 .Where(i => i.ID == id)
115.                 .Single();
116.             PopulateAssignedCourseData(instructor);
117.             if (instructor == null)
118.             {
119.                 return NotFound();
120.             }
121.             return View(instructor);
122.         }
123. 
124.         private void PopulateAssignedCourseData(Instructor instructor)
125.         {
126.             var allCourses = db.Courses;
127.             var instructorCourses = new HashSet<int>(instructor.CourseAssignments.Select(c => c.CourseID));
128.             var viewModel = new List<AssignedCourseData>();
129.             foreach (var course in allCourses)
130.             {
131.                 viewModel.Add(new AssignedCourseData
132.                 {
133.                     CourseID = course.CourseID,
134.                     Title = course.Title,
135.                     Assigned = instructorCourses.Contains(course.CourseID)
136.                 });
137.             }
138.             ViewBag.Courses = viewModel;
139.         }
140. 
141.         // POST: Instructors/Edit/5
142.         [HttpPost]
143.         [ValidateAntiForgeryToken]
144.         public async Task<ActionResult> Edit(int? id, string[] selectedCourses)
145.         {
146.             if (id == null)
147.             {
148.                 return new StatusCodeResult((int)HttpStatusCode.BadRequest);
149.             }
150.             var instructorToUpdate = db.Instructors
