using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private SchoolContext _context;
        private InstructorsController _controller;

        private SchoolContext CreateContext(string dbName = null)
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private InstructorsController CreateController(SchoolContext context)
        {
            var controller = new InstructorsController(context);
            var httpContext = new DefaultHttpContext();
            var tempData = new TempDataDictionary(httpContext, Mock.Of<ITempDataProvider>());
            controller.TempData = tempData;
            return controller;
        }

        private void SeedInstructorWithCourses(SchoolContext context)
        {
            var dept = new Department
            {
                Name = "Mathematics",
                Budget = 100000m,
                StartDate = DateTime.Parse("2007-09-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 1050,
                Title = "Calculus",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var instructor = new Instructor
            {
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = DateTime.Parse("2000-01-01"),
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1050 }
                }
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();
        }

        private void SeedMultipleInstructors(SchoolContext context)
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 200000m,
                StartDate = DateTime.Parse("2005-09-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course1 = new Course { CourseID = 2010, Title = "Physics", Credits = 4, DepartmentID = dept.DepartmentID };
            var course2 = new Course { CourseID = 2020, Title = "Chemistry", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            // Instructor with CourseAssignments - "Alpha" last name sorts first
            var instructor1 = new Instructor
            {
                LastName = "Alpha",
                FirstMidName = "Anna",
                HireDate = DateTime.Parse("2010-03-15"),
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 2010 },
                    new CourseAssignment { CourseID = 2020 }
                },
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };

            // Instructor without courses - "Beta" last name sorts second
            var instructor2 = new Instructor
            {
                LastName = "Beta",
                FirstMidName = "Bob",
                HireDate = DateTime.Parse("2015-08-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();
        }

        public void Dispose()
        {
            _controller?.Dispose();
            _context?.Dispose();
        }

        // ─── Index Tests ────────────────────────────────────────────────

        [Fact]
        public void Index_NoParams_ReturnsAllInstructorsOrdered()
        {
            _context = CreateContext();
            SeedMultipleInstructors(_context);
            _controller = CreateController(_context);

            var result = _controller.Index(null, null);

