using System;
using System.Text.Json;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        private static SchoolContext CreateContext()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            return new SchoolContext(options);
        }

        private static void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        private static void EnqueueNotifications(int count)
        {
            var svc = new NotificationService();
            for (int i = 0; i < count; i++)
            {
                svc.SendNotification("TestEntity", $"id-{i}", $"Item {i}", EntityOperation.CREATE, "TestUser");
            }
        }

        public NotificationsControllerTests()
        {
            _context = CreateContext();
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Arrange
            DrainNotificationQueue();

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            Assert.Contains("\"success\":true", json);
            Assert.Contains("\"count\":0", json);
            Assert.Contains("\"notifications\":[]", json);
        }

        [Fact]
        public void GetNotifications_WithMoreThan10_ReturnsExactly10()
        {
            // Arrange
            DrainNotificationQueue();
            EnqueueNotifications(15);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = JsonSerializer.Serialize(result.Value);
            Assert.Contains("\"success\":true", json);
            Assert.Contains("\"count\":10", json);

            // Verify 5 remain in the queue
            int remaining = 0;
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) remaining++;
            Assert.Equal(5, remaining);
        }

        [Fact]
        public void GetNotifications_LessThan10_ReturnsAll()
        {
            // Arrange
            DrainNotificationQueue();
            EnqueueNotifications(3);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = JsonSerializer.Serialize(result.Value);
            Assert.Contains("\"success\":true", json);
            Assert.Contains("\"count\":3", json);
        }

        [Fact]
        public void GetNotifications_ReturnsJsonResult()
        {
            // Arrange
            DrainNotificationQueue();

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void GetNotifications_NotificationsContainExpectedFields()
        {
            // Arrange
            DrainNotificationQueue();
            EnqueueNotifications(1);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = JsonSerializer.Serialize(result.Value);
            Assert.Contains("\"count\":1", json);
            Assert.Contains("\"success\":true", json);
            // Verify the notification has the expected entity data
            Assert.Contains("TestEntity", json);
            Assert.Contains("CREATE", json);
            Assert.Contains("TestUser", json);
        }

        [Fact]
        public void GetNotifications_Exactly10_ReturnsAll10()
        {
            // Arrange
            DrainNotificationQueue();
            EnqueueNotifications(10);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            var json = JsonSerializer.Serialize(result.Value);
            Assert.Contains("\"success\":true", json);
            Assert.Contains("\"count\":10", json);

            // Verify queue is now empty
            var svc = new NotificationService();
            Assert.Null(svc.ReceiveNotification());
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.IsType<JsonResult>(result);
            var json = JsonSerializer.Serialize(result.Value);
            Assert.Contains("\"success\":true", json);
            // Should not contain error message
            Assert.DoesNotContain("message", json);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_ReturnsSuccess()
        {
            // MarkAsRead is a no-op, any ID should succeed
            var ids = new[] { 0, -1, 42, int.MaxValue };
            foreach (var id in ids)
            {
                var result = _controller.MarkAsRead(id);
                var json = JsonSerializer.Serialize(result.Value);
                Assert.Contains("\"success\":true", json);
            }
        }

        [Fact]
        public void MarkAsRead_ReturnsJsonResult()
        {
            // Act
            var result = _controller.MarkAsRead(99);

            // Assert
            Assert.IsType<JsonResult>(result);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Null(viewResult.ViewName); // default view
        }
    }
}

