             Assert.NotNull(literature);
             Assert.Equal(2042, literature.CourseID);
             Assert.Equal(4, literature.Credits);
         }

         [Fact]
         public void Initialize_DepartmentInstructorRelationships_AreCorrect()
         {
             using var context = GetDbContext(Guid.NewGuid().ToString());
             DbInitializer.Initialize(context);

             // English department is led by Abercrombie
             var english = context.Departments.Single(d => d.Name == "English");
             var abercrombie = context.Instructors.Single(i => i.LastName == "Abercrombie");
             Assert.Equal(abercrombie.ID, english.InstructorID);

             // Mathematics department is led by Fakhouri
             var math = context.Departments.Single(d => d.Name == "Mathematics");
             var fakhouri = context.Instructors.Single(i => i.LastName == "Fakhouri");
             Assert.Equal(fakhouri.ID, math.InstructorID);

             // Engineering department is led by Harui
             var engineering = context.Departments.Single(d => d.Name == "Engineering");
             var harui = context.Instructors.Single(i => i.LastName == "Harui");
             Assert.Equal(harui.ID, engineering.InstructorID);

             // Economics department is led by Kapoor
             var economics = context.Departments.Single(d => d.Name == "Economics");
             var kapoor = context.Instructors.Single(i => i.LastName == "Kapoor");
             Assert.Equal(kapoor.ID, economics.InstructorID);
         }
